/** Typed access to the measured results (generated by scripts/export_web_results.py). */

import raw from "@/data/results.json";

export interface DatasetQuality {
  cases: number;
  answerable: number;
  unanswerable: number;
  correct: number;
  wrong: number;
  false_answers: number;
  median_seconds?: number;
}

export interface ProviderQuality {
  provider: string;
  label: string;
  grounding_min: number;
  public: DatasetQuality;
  private: DatasetQuality;
}

export interface Results {
  public_benchmark: {
    answerable: number;
    unanswerable: number;
    hit_at_1: number;
    hit_at_3: number;
    hit_at_5: number;
    mrr: number;
  };
  retrieval: { key: string; label: string; hit_at_1: number; hit_at_5: number; mrr: number }[];
  chunking: { key: string; label: string; hit_at_1: number; mrr: number }[];
  answer_quality: ProviderQuality[];
  old_gate: { label: string; public_correct: number; public_false_answers: number };
  gate_only_sweep_phi3_public: { threshold: number; correct: number; false_answers: number }[];
}

export const results = raw as Results;

export function quality(provider: "ollama" | "gemini"): ProviderQuality {
  const row = results.answer_quality.find((q) => q.provider === provider);
  if (!row) throw new Error(`No measured results for ${provider}`);
  return row;
}

/** Invented answers across both test sets, e.g. { count: 0, total: 28 }. */
export function inventedAnswers(q: ProviderQuality): { count: number; total: number } {
  const total = q.public.unanswerable + q.private.unanswerable;
  const count = Math.round(
    q.public.false_answers * q.public.unanswerable + q.private.false_answers * q.private.unanswerable,
  );
  return { count, total };
}
